      "height": 0,
      "howto": "① 예측 탭에서 10 M☉인 별의 주계열 수명이 1 M☉인 별과 어떻게 다를지 먼저 골라요.\n② 실험 탭 **한 별씩 보기**: **1 M☉인 별**과 **10 M☉인 별** 중 하나를 고르고 **진화 재생**을 누르거나 **진행** 슬라이더로 단계별 위치를 H-R도에서 확인해요.\n**두 별 동시 출발**: 같은 날 태어난 두 별을 **태어난 뒤** 시간 슬라이더(로그 눈금)로 함께 진화시켜, 아래 시간 막대에서 각 별이 주계열에 머무는 시간을 비교해요.\n① 예측 탭 아래 **실제 별** 버튼(태양·알데바란·베텔게우스·시리우스 B·게성운)으로 실제 별이 어느 진화 단계인지 H-R도에서 찾아봐요.\n③ 미션 탭의 도전 과제를 모두 달성해 보세요.",
      "concept": "별은 원시별 → 주계열성을 거쳐, 중심핵의 수소가 고갈되면 H-R도의 오른쪽 위로 이동해 거성(또는 초거성)이 됩니다.\n태양 정도의 별은 적색 거성 → 행성상 성운 → **백색 왜성**으로, 질량이 큰 별은 초거성 → 초신성 폭발 → **중성자별이나 블랙홀**로 진화합니다.\n질량이 클수록 진화 속도가 빠릅니다.",
