      "concept": "1 : 3이면 모원소가 전체의 **1/4 = 25 %**예요. 100 % → 50 % → 25 %이므로 반감기를 **2번** 지났어요. 절대연령 = 반감기 × 2예요.",
      "inquiry": "모원소 : 자원소 = 1 : 3인 광물은 반감기를 몇 번 지났을까요?\n모원소 : 자원소 = 1 : 7이면 반감기 몇 회인지 확인해 보세요.\n¹⁴C로 측정했을 때 절대연령이 약 11460년(±100년)인 시료의 모원소 비율을 찾아보세요.",
