      "howto": "① 예측 탭에서 안타레스를 태양 자리에 놓으면 표면이 어디까지 올지 골라 봐요.\n② 실험 탭: **배율** 슬라이더나 **확대/축소** 버튼으로 태양·아르크투루스·안타레스의 크기를 비교해요.\n**태양 자리에 놓기**를 누르면 행성 궤도 위에 안타레스가 겹쳐져요. 궤도를 눌러 안타레스 안인지 밖인지 확인해요.\n**나만의 별** 슬라이더로 반지름을 정해 크기(AU), 빛이 지름을 건너는 시간, 삼키는 궤도를 알아봐요.\n① 예측 탭 아래 **실제 행성 궤도**(수성·지구·화성·목성) 버튼으로 궤도 반지름을 안타레스와 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "태양의 반지름은 약 70만 km, 거성 아르크투루스는 약 2천만 km, 초거성 **안타레스**는 약 4억 7천만 km입니다.\n안타레스를 태양 자리에 두면 화성 궤도를 훨씬 넘어설 만큼 큽니다.",
      "inquiry": "안타레스의 반지름은 태양의 약 몇 배일까?\n초거성의 표면 온도가 낮은데도 광도가 매우 큰 까닭은?",
