      "howto": "① 예측 탭에서 온도가 2배가 되면 최대 복사 파장이 어떻게 될지 골라 봐요.\n② 실험 탭: **표면 온도** 슬라이더로 곡선의 높이, 봉우리 위치, 별의 색 변화를 관찰해요. **현재 곡선 남기기**로 여러 곡선을 겹쳐 비교해요.\n그래프의 보라색 **손잡이 두 개**를 끌어 파장 구간을 고르면 그 구간에서 나오는 에너지 비율을 알려 줘요. 아래 막대는 자외선·가시광선·적외선 비율이에요.\n**? 미지의 별 온도 맞히기**를 누르고, 회색 점선 곡선에 내 곡선을 겹쳐 온도를 맞혀요.\n**실제 별**(베텔게우스·태양·베가·리겔) 버튼으로 실제 별의 온도와 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "별은 흑체에 가까워 온도에 따라 복사 에너지 분포가 달라집니다.\n**빈의 변위 법칙**(λmax = 2.898×10⁻³/T): 온도가 높을수록 최대 에너지를 방출하는 파장이 짧아져 별이 파랗게 보입니다.\n**슈테판·볼츠만 법칙**(E = σT⁴): 온도가 높을수록 단위 면적에서 방출하는 에너지가 매우 많아집니다.",
      "inquiry": "표면 온도가 2배가 되면 최대 복사 파장과 단위 면적당 에너지는 어떻게 변할까?\n붉은 별과 파란 별 중 표면 온도가 높은 별은?",
