      "howto": "① 예측 탭에서 30개 별이 H-R도의 어디에 가장 많이 모일지 먼저 골라요.\n② 실험 탭: **직접 찍기**를 누르면 별의 분광형과 절대 등급이 나와요. 그래프에서 그 자리를 직접 눌러 찍어요(틀리면 방향을 알려 줘요).\n**한 개씩 찍기**나 **모두 찍기**로 나머지 별을 찍고, 점을 눌러 별 이름을 확인해요. **무리 표시 켜기/끄기**로 주계열성·거성·초거성·백색왜성 영역을 봐요.\n**13광년 안의 가까운 별**과 **밤하늘의 1등성** 버튼으로 골라 보는 별에 따라 H-R도가 어떻게 달라 보이는지 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "**H-R도**는 가로축에 분광형(표면 온도), 세로축에 절대 등급(광도)을 나타낸 그래프입니다.\n별들은 왼쪽 위에서 오른쪽 아래로 이어지는 **주계열성**, 오른쪽 위의 **거성·초거성**, 왼쪽 아래의 **백색 왜성**으로 무리 지어 분포합니다.\n관측되는 별의 약 90 %는 주계열성입니다.",
