      "howto": "① 예측 탭에서 광도가 같고 온도가 2배인 별의 반지름을 먼저 골라요.\n② 실험 탭: H-R도의 **점을 끌어** 원하는 위치로 옮기고, **태양·적색거성·초거성·백색왜성** 버튼으로 빠르게 이동해요. 그 위치의 별 색·반지름·무리와 **복사 세기 분포**(최대 세기 파장)를 확인해요.\n**반지름 고정**·**광도 고정**을 누르면 별이 노란 선을 따라서만 움직여, L = 4πR²σT⁴ 관계를 직접 확인할 수 있어요.\n① 예측 탭 아래 **실제 별** 버튼(시리우스 A·아르크투루스·프록시마 센타우리·베텔게우스)으로 계산한 반지름과 측정된 반지름을 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "H-R도에서 오른쪽 위로 갈수록 반지름이 큰 별입니다(같은 온도에서 광도가 크면 반지름이 큼).\n**거성·초거성**은 표면 온도가 낮지만 반지름이 매우 커서 광도가 크고, **백색 왜성**은 온도가 높지만 반지름이 매우 작아 광도가 작습니다.",
      "inquiry": "H-R도의 오른쪽 위에 있는 별의 반지름이 큰 까닭은?\n백색 왜성이 표면 온도가 높은데도 어두운 까닭은?",
