      "howto": "① 예측 탭에서 태양 같은 별의 최후를 먼저 골라요.\n② 실험 탭: **중심핵 질량** 슬라이더를 정하고 **▶ 최후 맞이하기**를 눌러 백색 왜성·중성자별·블랙홀 중 무엇으로 남는지 확인해요.\n**압축 실험실**: **반지름** 슬라이더나 아래 눈금을 **끌어** 같은 질량을 점점 작게 눌러 보세요. 탈출 속도가 빛의 속도에 가까워지고, **사건의 지평선** 안으로 들어가면 빛도 빠져나오지 못해요.\n**실제로 발견된 별의 최후**(① 예측 탭 아래)로 시리우스 B, 고리 성운, 게 성운 펄서, 백조자리 X-1을 살펴봐요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
