      "howto": "① 예측 탭에서 원시별이 만들어지기 좋은 성운을 먼저 골라요.\n② 실험 탭: **성운 온도**와 **성운 밀도** 슬라이더를 바꾸거나 **차가운 성운·뜨거운 성운** 버튼을 눌러요. 알갱이들이 중력으로 모이는지 흩어지는지 관찰하고, **다시 시작**으로 반복해요.\n아래 그래프에 **중심에 모인 물질(%)**이 시간에 따라 기록되고, 지난 실험 세 번이 회색으로 남아 조건을 비교할 수 있어요.\n**실제 성운과 비교** 버튼으로 바너드 68, 창조의 기둥, 오리온 성운과 비슷한 조건을 불러와요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
