      "howto": "① 예측 탭에서 나선 은하를 옆면에서 보면 어떻게 보일지 먼저 골라요. 아래 **실제 은하 불러오기**로 우리은하, 안드로메다, 소용돌이, 솜브레로, M87, 대마젤란은하를 모형으로 만들어 볼 수 있어요.\n② 실험 탭 **은하 만들기**: E0~E7, S0, Sa~Sc, SBa~SBc, Irr 버튼으로 은하를 만들고, **보는 각도** 슬라이더로 정면(0°)에서 옆면(88°)까지 기울여 봐요. 그림을 **좌우로 끌면** 은하가 돌아가요.\n**분류 도전 10문제**: 화면의 은하를 보고 타원·정상나선·막대나선·불규칙 은하 중 하나를 골라요. **어려움**을 켜면 여러 방향으로 기울어진 은하가 나와요. **새로 시작**으로 다시 도전해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
