      "howto": "① 예측 탭에서 Hα와 Hβ 중 어느 선이 더 많이 이동할지 골라요. 아래 **실제 퀘이사** 버튼으로 3C 273, 3C 48, 가장 먼 퀘이사를 불러와요.\n② 실험 탭: **적색 편이 z** 슬라이더나 **정지·3C 273** 버튼으로 수소 방출선(Hα~Hε)이 긴 파장 쪽으로 이동하는 모습과 관측 파장을 확인해요.\n방출선 그래프를 **찍어 파장을 재면** 아래 **계산 노트**에 z, 후퇴 속도(v ≈ cz), 허블 법칙으로 어림한 거리가 계산돼요.\n**미지의 퀘이사 맞히기**: [새 퀘이사 관측]을 누르고 회색 관측 스펙트럼에 모형 선이 겹치도록 z를 맞춘 뒤 [z 확인]을 눌러요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "**퀘이사**는 매우 멀리 있어 별처럼 보이지만 막대한 에너지를 방출하는 활동 은하의 중심부로, 큰 **적색 편이**를 보입니다.\n적색 편이 z = (λ − λ₀)/λ₀이며, 관측 파장은 λ = λ₀(1 + z)입니다. 모든 방출선이 같은 비율로 이동합니다.\n3C 273의 적색 편이는 약 0.158입니다.",
