      "height": 0,
      "howto": "① 예측 탭에서 3000 K의 빛이 지금 어떤 빛으로 관측될지 골라 봐요.\n② 실험 탭: **팽창 배율** 슬라이더나 **38만 년·현재** 버튼, **▶ 자동**으로 곡선의 봉우리(최대 복사 파장)와 온도, 적색 편이 변화를 확인해요.\n그래프의 파란 **검출기 창**을 끌어 어느 파장에서 우주 배경 복사를 가장 잘 받는지 찾아요(가시광선 망원경·적외선 망원경·전파 안테나).\n① 예측 탭 아래 **실제 관측**(빛이 풀려난 때, 펜지어스·윌슨 1965, COBE 위성)을 불러와 비교해요.\n③ **🎯 미션 시작** 버튼을 눌러 도전 과제를 해결해 보세요.",
      "concept": "우주 나이 약 38만 년, 온도가 약 3000 K일 때 원자가 형성되며 빛이 자유롭게 진행하기 시작했습니다.\n이 빛은 우주가 팽창하는 동안 파장이 길어져 현재 약 **2.73 K** 흑체 복사에 해당하는 마이크로파로 모든 방향에서 관측됩니다(**우주 배경 복사**).\n1964년 펜지어스와 윌슨이 발견했습니다.",
      "inquiry": "우주가 약 1100배 팽창하는 동안 최대 복사 파장은 어떻게 변했을까?\n우주 배경 복사가 모든 방향에서 거의 같게 관측되는 것은 무엇을 뜻할까?",
