      "concept": "거리 r인 은하가 속도 v로 멀어진다면, 멀어지기 시작한 때부터 지금까지 걸린 시간은 r/v = 1/H입니다.\nH = 70 km/s/Mpc이면 1/H ≈ 140억 년으로, 현재 알려진 우주의 나이(약 138억 년)와 비슷합니다.\n허블 상수가 클수록 우주의 나이는 적게 계산됩니다.",
