      "concept": "해양판은 해령에서 멀어지며 식어 **밀도가 커지고 두꺼워져요**.\n**섭입하는 판이 당기는 힘**: 무거운 판이 중력으로 가라앉으며 판 전체를 끌어요 → 주요 원동력\n**해령에서 미는 힘**: 높은 해령에서 판이 경사면을 따라 미끄러져요 → 당기는 힘보다 작아요.",
