      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **❚❚ 멈춤**, **속도: 1시간/초**, **+1일**, **A 고위도 70°**, **B 중위도 37°**, **C 적도**, **☀ 태양 기조력**, **달의 적위** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "지구와 달이 공통 질량 중심을 돌 때 생기는 **원심력**은 지구 어디서나 같아요.\n달의 **만유인력**은 가까운 곳일수록 커요. 둘의 합력이 **기조력**이에요.\n달 쪽과 그 반대쪽이 **만조**, 그 사이가 **간조**가 돼요.\n달이 하루 약 13° 공전해 조석 주기는 약 **12시간 25분**, 만조는 매일 약 50분씩 늦어져요.\n달의 기조력은 태양의 약 2배 · 삭·망 → **사리**, 상현·하현 → **조금**",
      "inquiry": "오늘은 음력 15일, 보름달이에요. 바다의 상태는?\n힘 화살표를 켜서 달 쪽과 반대쪽의 기조력을 비교해 보세요.\n관측 지점을 A(고위도)로 바꿔 일주조를 관찰해 보세요.",
      "added": "2026-10-27",
