      "concept": "예보표에는 날짜(양력·음력), **고조(만조)·저조(간조)** 시각과 높이(cm), 대조기·소조기가 있어요.\n만조와 다음 만조 사이 = **조석 주기** → 평균 약 **12시간 25분**\n같은 물때의 만조 시각은 매일 약 **50분**씩 늦어져요.\n조차는 약 15일 간격으로 커졌다(**사리**, 삭·망 무렵) 작아졌다(**조금**, 상현·하현 무렵) 해요.\n서해안은 조차가 크고 동해안은 아주 작아요.",
