      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **이산화 탄소** 슬라이더를 움직여요.\n**🔍 미지의 대기**, **판정**, **↺ 현재 지구** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "태양(약 5800 K)은 **가시광선**, 지구(약 288 K)는 **적외선** 영역에서 가장 강하게 복사해요.\n산소·오존은 해로운 **자외선**을 흡수하고, 가시광선은 대부분 지표까지 와요.\n수증기·이산화 탄소·메테인 등 **온실 기체**는 지구 복사를 흡수했다가 지표로 **재복사**해 기온을 높여요 → 온실 효과\n약 8~12 μm는 지구 복사가 거의 흡수되지 않고 빠져나가는 **대기의 창**이에요.",
