      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **지구의 반사율**, **대기의 흡수율** 슬라이더를 움직여요.\n**현재 지구**, **온실 기체 증가**, **🌋 화산 폭발**, **빙하 지구**, **⏩ 빠르게**, **🧩 열수지 퍼즐**, **확인** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "반사 **30**(대기·구름 23, 지표 7), 흡수 **70**(대기 19, 구름 4, 지표 47)\n지표는 지구 복사 **116**을 방출 → 대기가 104 흡수, **12**는 대기의 창으로 우주로\n지표 → 대기: **잠열 24**(증발·응결), **대류·전도 5**\n대기 → 지표 **재복사 98**(온실 효과), 대기 → 우주 49 + 구름 9\n우주 100 = 30 + 70, 대기 156 = 156, 지표 145 = 145 → **복사 평형**",
