      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **지면 기온**, **지면 이슬점**, **높이** 슬라이더를 움직여요.\n**⬆ 꼭대기로**, **⬇ 지면으로**, **교과서 예제** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "주변과 열을 주고받지 않고 부피가 변해 기온이 바뀌는 현상을 **단열 변화**라고 해요.\n상승 → 기압↓ → **단열 팽창** → 기온↓ (팽창하며 일을 해 내부 에너지 감소)\n하강 → 기압↑ → **단열 압축** → 기온↑\n불포화: **건조 단열 감률 약 10 ℃/km**, 이슬점은 약 2 ℃/km 감소\n포화: 응결하며 **잠열**이 나와 **습윤 단열 감률 약 5 ℃/km**로 천천히 식어요.",
