      "concept": "Γ &lt; 습윤 단열 감률(5 ℃/km) → **절대 안정**: 밀어 올리면 주변보다 차가워 되돌아와요.\nΓ &gt; 건조 단열 감률(10 ℃/km) → **절대 불안정**: 계속 상승해요.\n5 &lt; Γ &lt; 10 → **조건부 불안정**: 불포화면 안정, 포화면 불안정\n안정한 대기의 강제 상승 → **층운형 구름**, 불안정한 대기 → **적운형 구름**\n**기온 역전층**은 매우 안정해 연기·오염 물질이 위로 퍼지지 못해요.",
      "inquiry": "기온 감률이 건조 단열 감률(10 ℃/km)보다 큰 대기에서 불포화 공기 덩어리를 살짝 밀어 올리면?\n절대 안정한 대기에서 밀어 올린 공기 덩어리가 제자리로 돌아오는 것을 확인해 보세요.\n절대 불안정한 대기에서 공기 덩어리가 계속 올라가는 것을 확인해 보세요.",
