      "status": "ready",
      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **상승 기류**, **물방울 크기 차**, **차가운 구름** 슬라이더를 움직여요.\n**🧂 소금 살포**, **❄ 요오드화 은**, **지상 0 ℃ 이상**, **↺ 새 구름**, **🛩 인공 강우 작전**, **작전 개시** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**병합 과정**: 따뜻한 구름(저위도)에서 큰 물방울이 빨리 떨어지며 작은 물방울과 충돌해 합쳐져요.\n물방울 크기가 다양할수록, 상승 기류가 강해 오래 머물수록 잘 자라요.\n**빙정 과정**: −40~0 ℃ 구름에는 과냉각 물방울과 빙정이 함께 있어요. 같은 온도에서 **과냉각 물방울의 포화 수증기압 &gt; 빙정**\n그래서 물방울은 증발하고 그 수증기가 빙정에 붙어 빙정이 커져요(약 −12 ℃에서 가장 활발).\n무거워진 빙정이 녹으면 **비**, 녹지 않으면 **눈**이에요. 중·고위도 강수의 대부분이에요.",
      "inquiry": "−12 ℃ 구름 속에 과냉각 물방울과 빙정이 함께 있으면 어떤 일이 일어날까요?\n따뜻한 구름에서 병합 과정으로 비를 내리게 해 보세요.\n차가운 구름을 −40 ℃ 이하로 낮추면 어떻게 되는지 확인해 보세요.",
