      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **공기 덩어리 높이**, **높이 차 ΔZ**, **등압선 간격**, **공기 밀도** 슬라이더를 움직여요.\n**① 정역학 평형**, **② 수평 기압 경도력**, **평형**, **중력 끄기**, **기압 경도력 끄기**, **▶ 공기 덩어리 놓기** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "기압 경도력은 **기압이 높은 곳 → 낮은 곳**으로, 등압선에 직각으로 작용해요.\n위로 작용하는 **연직 기압 경도력**과 아래로 작용하는 **중력**이 같아 공기가 위로 날아가지 않아요 → **정역학 평형**\n정역학 방정식: **ΔP = ρgΔZ** (밀도 1.226 kg/m³ → 1000 m에 약 120 hPa)\n연직 방향 힘은 상쇄되므로 바람을 일으키는 근본적인 힘은 **수평 기압 경도력**이에요.",
