      "concept": "따뜻한 쪽 공기 기둥은 **팽창**, 차가운 쪽은 **수축** → 지표 기압은 아직 같아요.\n같은 높이에서는 팽창한 쪽 기압이 높아 **상층**에서 따뜻한 쪽 → 차가운 쪽으로 공기가 이동해요.\n공기가 쌓인 차가운 쪽 지표는 **고기압**, 빠져나간 따뜻한 쪽 지표는 **저기압**이 돼요.\n지상에서는 차가운 쪽 → 따뜻한 쪽으로 바람, 따뜻한 쪽 **상승**, 차가운 쪽 **하강** → 순환 완성\n낮: 바다 → 육지 **해풍** / 밤: 육지 → 바다 **육풍**",
