      "height": 0,
      "howto": "① 예측 탭에서 질문의 답을 먼저 골라요.\n② 실험 탭: **자전 없음 (단일 세포)**, **자전 (3세포)**, **지상풍**, **기압대 이름**, **에너지 수송이 없다면?**, **🧭 바람 지도 탐험** 버튼을 눌러 봐요.\n그림을 직접 누르거나 끌어서 조작할 수도 있어요.\n③ 개념 탭에서 핵심 개념을 정리하고, **🎯 미션** 버튼으로 도전 과제를 해결해 보세요.",
      "concept": "**해들리 순환**(0~30°): 적도에서 상승 → 30° 부근 하강(아열대 고압대) → 지상 **무역풍**\n**페렐 순환**(30~60°): 두 순환 사이에서 간접적으로 생겨요 → 지상 **편서풍**\n**극순환**(60~90°): 극에서 하강 → 지상 **극동풍** → 60° 부근 **한대 전선대**\n적도 저압대는 상승 기류로 비가 많고, 30° 부근 고압대는 하강 기류로 건조해 **사막**이 많아요.\n자전이 없으면 전향력이 없어 반구마다 하나의 커다란 세포(**단일 세포**)가 생겨요.",
      "inquiry": "위도 30° 부근(사하라, 아라비아 등)에 사막이 많은 까닭은 무엇일까요?\n자전하지 않는 지구(단일 세포)의 지상풍을 3세포와 비교해 보세요.\n‘에너지 수송이 없다면?’을 켜서 기온 분포가 어떻게 달라지는지 확인해 보세요.",
      "added": "2026-10-27",
